function placeLabels(viewportWidth, viewportHeight, labels) {
  const finiteNonNegative = value => Number.isFinite(value) && value >= 0;
  if (!finiteNonNegative(viewportWidth) || !finiteNonNegative(viewportHeight)) {
    throw new TypeError('viewport dimensions must be finite non-negative numbers');
  }
  if (!Array.isArray(labels)) throw new TypeError('labels must be an array');
  for (const label of labels) {
    if (!label || typeof label !== 'object' || Array.isArray(label) ||
        typeof label.text !== 'string' || typeof label.color !== 'string' ||
        !finiteNonNegative(label.width) || !finiteNonNegative(label.height)) {
      throw new TypeError('invalid label');
    }
  }
  const totalHeight = labels.reduce((sum, label) => sum + label.height, 0) +
    labels.length * 8;
  let top = (viewportHeight - totalHeight) / 2;
  return labels.map(label => {
    const result = {
      text: label.text,
      width: label.width,
      height: label.height,
      color: label.color,
      left: (viewportWidth - label.width) / 2,
      top
    };
    top += label.height + 8;
    return result;
  });
}

module.exports = { placeLabels };

