'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api).sort(), ['placeLabels']);
const { placeLabels } = api;

const labels = [
  { text: 'A', width: 20, height: 10, color: 'red' },
  { text: 'B', width: 40, height: 20, color: 'blue' },
  { text: 'C', width: 10, height: 6, color: '' }
];
const snapshot = structuredClone(labels);
const result = placeLabels(100, 80, labels);
assert.deepEqual(result, [
  { text: 'A', width: 20, height: 10, color: 'red', left: 40, top: 14 },
  { text: 'B', width: 40, height: 20, color: 'blue', left: 30, top: 32 },
  { text: 'C', width: 10, height: 6, color: '', left: 45, top: 60 }
]);
assert.deepEqual(labels, snapshot);
assert.notStrictEqual(result[0], labels[0]);
result[0].text = 'changed';
assert.equal(labels[0].text, 'A');

assert.deepEqual(placeLabels(0, 0, []), []);
assert.deepEqual(placeLabels(10, 10, [{ text: 'wide', width: 30, height: 20, color: 'x' }]), [
  { text: 'wide', width: 30, height: 20, color: 'x', left: -10, top: -5 }
]);
assert.deepEqual(placeLabels(5.5, 4.5, [{ text: '', width: 0, height: 0, color: '' }]), [
  { text: '', width: 0, height: 0, color: '', left: 2.75, top: 2.25 }
]);

for (const args of [[-1, 2, []], [1, -2, []], [NaN, 2, []], [1, Infinity, []], ['1', 2, []], [1, 2, null]]) {
  assert.throws(() => placeLabels(...args), TypeError);
}
for (const bad of [null, {}, { text: 1, width: 1, height: 1, color: 'x' }, { text: 'x', width: -1, height: 1, color: 'x' }, { text: 'x', width: 1, height: Infinity, color: 'x' }, { text: 'x', width: 1, height: 1, color: null }]) {
  assert.throws(() => placeLabels(10, 10, [bad]), TypeError);
}

